def metric(data: pd.DataFrame) -> float:
    is_tie = data.apply(lambda row: sum(row['option_a_ratings']) == sum(row['option_b_ratings']), axis=1)
    tie_trials = data[is_tie]
    if len(tie_trials) == 0:
        return 0.5
    return (tie_trials['response'] == 0).mean()

